-- v1.3 更新公告（2026-10-21）
-- 双目的：① 更正 v1.2 第 6 条失实表述（「工具栏直达」与实际入口不符）；
--         ② 公告本轮智能匹配入口全面开放。版本号 v1.2→v1.3，保证全员弹一次看到更正。
-- 写入方式与 PUT /auth/settings/changelog 一致（site_settings.key = app_changelog）
INSERT INTO site_settings (key, value) VALUES ('app_changelog', '{"version":"v1.3","title":"v1.3 更新公告：智能匹配全站直达","updated_at":"2026-10-21","items":["智能匹配入口全面开放：侧栏「人才资产 → 智能匹配」常驻菜单，人才库工具栏、AI 助手「看人」组、岗位管理每行「匹配人才」（按岗位标题自动找同名画像）均可进入，招聘看板「简历筛选」列空态也可一键补人","说明更正：v1.2 公告中「智能匹配不再藏着：工具栏直达」一句与当时实际入口不符（当时实际入口是人才详情页头部的「智能匹配」按钮），以本条为准，抱歉造成误会","智能匹配的使用数据已可在「日志管理」单独查看（此前与「人才画像」合并统计，看不出这个功能到底有多少人在用）","帮助中心新增「智能匹配怎么用」说明；新手指引加入匹配实操步骤，老用户可点右上角 ? 图标选择「重看新手指引」补看"]}')
ON CONFLICT(key) DO UPDATE SET value = excluded.value;
